private void frmRegister_Load(object sender, EventArgs e)
{
    // Each picture's Tag holds its file name, set in Properties
    pictures = new PictureBox[] { picGoat, picEagle, picFox, picHare,
        picDeer, picOwl, picBadger, picRaven };
    foreach (PictureBox pic in pictures)
    {
        pic.Image = Files.Picture("Avatars", (string)pic.Tag);
    }
}

// Every avatar picture runs this: its frame turns gold
private void Avatar_Click(object sender, EventArgs e)
{
    PictureBox clicked = (PictureBox)sender;
    foreach (PictureBox pic in pictures)
    {
        pic.Parent.BackColor = Color.Transparent;   // no frame
    }
    clicked.Parent.BackColor = Color.FromArgb(242, 183, 5);
    chosenAvatar = (string)clicked.Tag;
    lblAvatarError.Text = "";
}

