// Checks every box, shows each box's own message, then saves
private void btnCreate_Click(object sender, EventArgs e)
{
    lblUsernameError.Text = "";
    lblPasswordError.Text = "";
    lblAgainError.Text = "";
    lblAvatarError.Text = "";
    bool allRight = true;
    Player player = new Player();
    try
    {
        player.Username = txtUsername.Text;   // rules 1, 2 and 3
    }
    catch (SummitException ex)
    {
        lblUsernameError.Text = ex.Message;
        allRight = false;
    }
    try
    {
        player.Password = txtPassword.Text;   // rules 5 to 8
    }
    catch (SummitException ex)
    {
        lblPasswordError.Text = ex.Message;
        allRight = false;
    }
    try
    {
        Player.CheckPasswordsMatch(txtPassword.Text, txtAgain.Text);
    }
    catch (PasswordMismatchException ex)
    {
        lblAgainError.Text = ex.Message;      // rule 10
        txtPassword.Text = "";
        txtAgain.Text = "";
        allRight = false;
    }
    catch (SummitException ex)
    {
        lblAgainError.Text = ex.Message;      // rule 9
        allRight = false;
    }
    try
    {
        player.Avatar = chosenAvatar;         // rule 11
    }
    catch (SummitException ex)
    {
        lblAvatarError.Text = ex.Message;
        allRight = false;
    }

if (!allRight) return;
try
{
    PlayerFile.Add(player);               // rule 4
}
catch (PlayerExistsException ex)
{
    lblUsernameError.Text = ex.Message;
    return;
}
NewUsername = player.Username;
MessageBox.Show("Your player " + player.Username + " is ready. "
    + "Log in to start your expedition.", "Player created");
this.Close();

